<?php use Aibid\Http\View as V; ?>
<div class="pagination-bar"><span><?= (int) $listing['total'] ?> registros · Página <?= (int) $listing['page'] ?> de <?= (int) $listing['pages'] ?></span><nav aria-label="Paginación" class="d-flex gap-2"><?php if ($listing['page'] > 1): ?><a class="btn btn-sm btn-outline-secondary" href="?<?= V::escape(http_build_query($filters + ['page' => $listing['page'] - 1])) ?>">Anterior</a><?php endif; ?><?php if ($listing['page'] < $listing['pages']): ?><a class="btn btn-sm btn-outline-secondary" href="?<?= V::escape(http_build_query($filters + ['page' => $listing['page'] + 1])) ?>">Siguiente</a><?php endif; ?></nav></div>
